<include file="Public:header"/><div class="mainbox">    <div id="nav" class="mainnav_title">        <ul>            <a href="{pigcms{:U('National_phone/index')}" class="on">区号列表</a>			<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('National_phone/create')}','添加国际区号',600,400,true,false,false,addbtn,'edit',true);">添加国际区号</a>                    </ul>    </div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('National_phone/index')}" method="get">                    <input type="hidden" name="c" value="National_phone"/>                    <input type="hidden" name="a" value="index"/>                    筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>					<select name="searchtype">						<option value="code" <if condition="$_GET['searchtype'] eq 'code'">selected="selected"</if>>区号</option>						<option value="national" <if condition="$_GET['searchtype'] eq 'national'">selected="selected"</if>>国家名称</option>					</select>					<input type="submit" value="查询" class="button"/>                </form>            </td>        </tr>    </table>    <form name="myform" id="myform" action="" method="post">        <div class="table-list">            <table width="100%" cellspacing="0">                <colgroup>                    <col width="180"/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col width="180" align="center"/>                </colgroup>                <thead>                <tr>                    <th>排序（越大越前）</th>                    <th>区号</th>                    <th>国家名称</th>                    <th>长度</th>                    <th>匹配规则</th>                    <th>状态</th>                    <th class="textcenter">操作</th>                </tr>                </thead>                <tbody>                <if condition="is_array($list)">                    <volist name="list" id="vo">                        <tr>                            <td>{pigcms{$vo.sort}</td>                            <td>{pigcms{$vo.code}</td>                            <td>{pigcms{$vo.national}</td>                            <td>{pigcms{$vo.length}</td>                            <td>{pigcms{$vo.match}</td>                            <td><if condition="$vo['status'] eq 1"><font color="green">启用</font><elseif condition="$vo['status'] eq 0"/><font color="red">禁用</font></if></td>                            <td class="textcenter">                                <!--<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Article/edit',array('id'=>$vo['id'],'frame_show'=>true))}','查看分类信息',480,260,true,false,false,false,'detail',true);">查看</a> | -->                                <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('National_phone/edit',array('id'=>$vo['id']))}','编辑国际区号',600,400,true,false,false,editbtn,'edit',true);">编辑</a> |                                <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('delete')}">删除</a>                            </td>                        </tr>                    </volist>                    <tr><td class="textcenter pagebar" colspan="7">{pigcms{$page}</td></tr>                    <else/>                    <tr><td class="textcenter red" colspan="7">列表为空！</td></tr>                </if>                </tbody>        </div>    </form></div><include file="Public:footer"/>